    /**
     * @method
     * @name bitstamp#fetchMarkets
     * @description retrieves data on all markets for bitstamp
     * @see https://www.bitstamp.net/api/#tag/Market-info/operation/GetTradingPairsInfo
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} an array of objects representing market data
     */
    public async override Task<List<ccxt.MarketInterface>> FetchMarkets(object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        List<object> response = ccxt.BaseExchange.FromDictList(await this.FetchMarketsFromCache(parameters));
        //
        //    [
        //
        //   spot:
        //
        //        {
        //            "name": "BTC/USD",
        //            "market_symbol": "btcusd",
        //            "base_currency": "BTC",
        //            "base_decimals": 8,
        //            "counter_currency": "USD",
        //            "counter_decimals": 0,
        //            "minimum_order_value": "10",
        //            "trading": "Enabled",
        //            "instant_order_counter_decimals": 2,
        //            "instant_and_market_orders": "Enabled",
        //            "description": "Bitcoin / U.S. dollar",
        //            "market_type": "SPOT"
        //        },
        //        ...
        //
        //    perp:
        //
        //         {
        //             "name": "BTC/USD-PERP",
        //             "market_symbol": "btcusd-perp",
        //             "base_currency": "BTC",
        //             "base_decimals": 5,
        //             "counter_currency": "USD",
        //             "counter_decimals": 0,
        //             "minimum_order_value": "10",
        //             "maximum_order_value": "500000.00000000",
        //             "minimum_order_amount": "0.00001000",
        //             "maximum_order_amount": "10.00000000",
        //             "trading": "Enabled",
        //             "instant_order_counter_decimals": 2,
        //             "instant_and_market_orders": "Enabled",
        //             "description": "Bitcoin / U.S. dollar Perpetual",
        //             "market_type": "PERPETUAL",
        //             "underlying_asset": "Kaiko BTC Benchmark Reference Rate",
        //             "payoff_type": "Linear",
        //             "contract_size": "1.00000000",
        //             "isin": "EZHKD4DNKHY3"
        //         }
        //
        List<object> result = new List<object>() {};
        for (int i = 0; i < (response?.Count ?? 0); i++)
        {
            object market = response[i];
            var baseIdquoteIdVariable = new List<object> {this.safeString(market, "base_currency"), this.safeString(market, "counter_currency")};
            var baseId = baseIdquoteIdVariable[0];
            var quoteId = baseIdquoteIdVariable[1];
            string? bs = this.safeCurrencyCode(baseId);
            string? quote = this.safeCurrencyCode(quoteId);
            if (((bs == null)) || ((quote == null)))
            {
                continue;
            }
            object settleId = null;
            string? marketTypeRaw = this.safeString(market, "market_type");
            string symbol = ((bs + "/") + quote);
            string? type = null;
            string? subType = null;
            if (marketTypeRaw == "SPOT")
            {
                type = "spot";
            } else if (marketTypeRaw == "PERPETUAL")
            {
                type = "swap";
                settleId = quoteId;
                symbol = ((((bs + "/") + quote) + ":") + (settleId));
                string? payoffType = this.safeString(market, "payoff_type");
                if (payoffType == "Linear")
                {
                    subType = "linear";
                } else if (payoffType == "Inverse")
                {
                    subType = "inverse";
                }
            }
            bool isSpot = (type == "spot");
            string? settle = ((settleId != null) && !isEqual(settleId, "")) ? this.safeCurrencyCode(settleId) : null;
            result.Add(new Dictionary<string, object>() {
                { "id", this.safeString(market, "market_symbol") },
                { "symbol", symbol },
                { "base", bs },
                { "quote", quote },
                { "settle", settle },
                { "baseId", baseId },
                { "quoteId", quoteId },
                { "settleId", settleId },
                { "type", type },
                { "subType", subType },
                { "spot", isSpot },
                { "margin", false },
                { "future", false },
                { "swap", !isSpot },
                { "option", false },
                { "active", ((this.safeString(market, "trading") == "Enabled")) },
                { "contract", !isSpot },
                { "linear", isSpot ? null : true },
                { "inverse", isSpot ? null : false },
                { "contractSize", null },
                { "expiry", null },
                { "expiryDatetime", null },
                { "strike", null },
                { "optionType", null },
                { "precision", new Dictionary<string, object>() {
                    { "amount", this.parseNumber(this.parsePrecision(this.safeString(market, "base_decimals"))) },
                    { "price", this.parseNumber(this.parsePrecision(this.safeString(market, "counter_decimals"))) },
                } },
                { "limits", new Dictionary<string, object>() {
                    { "leverage", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "amount", new Dictionary<string, object>() {
                        { "min", this.safeNumber(market, "minimum_order_amount") },
                        { "max", this.safeNumber(market, "maximum_order_amount") },
                    } },
                    { "price", new Dictionary<string, object>() {
                        { "min", null },
                        { "max", null },
                    } },
                    { "cost", new Dictionary<string, object>() {
                        { "min", this.safeNumber(market, "minimum_order_value") },
                        { "max", this.safeNumber(market, "maximum_order_value") },
                    } },
                } },
                { "created", null },
                { "info", market },
            });
        }
        return ccxt.BaseExchange.ToMarketInterfaceList(result);
    }

    public virtual Dictionary<string, object> constructCurrencyObject(object id, object code, object name, object precision, object minCost, object originalPayload)
    {
        string currencyType = "crypto";
        Dictionary<string, object> description = this.describe();
        if (this.isFiat(code))
        {
            currencyType = "fiat";
        }
        double? tickSize = this.parseNumber(this.parsePrecision(this.numberToString(precision)));
        return new Dictionary<string, object>() {
            { "id", id },
            { "code", code },
            { "info", originalPayload },
            { "type", currencyType },
            { "name", name },
            { "active", true },
            { "deposit", null },
            { "withdraw", null },
            { "fee", this.safeNumber(getValue(getValue((description != null && ((IDictionary<string, object>)description).ContainsKey("fees") ? ((IDictionary<string, object>)description)["fees"] : null), "funding"), "withdraw"), code) },
            { "precision", tickSize },
            { "limits", new Dictionary<string, object>() {
                { "amount", new Dictionary<string, object>() {
                    { "min", tickSize },
                    { "max", null },
                } },
                { "price", new Dictionary<string, object>() {
                    { "min", tickSize },
                    { "max", null },
                } },
                { "cost", new Dictionary<string, object>() {
                    { "min", minCost },
                    { "max", null },
                } },
                { "withdraw", new Dictionary<string, object>() {
                    { "min", null },
                    { "max", null },
                } },
            } },
            { "networks", new Dictionary<string, object>() {} },
        };
    }

    public async virtual Task<List<Dictionary<string, object>>> FetchMarketsFromCache(object parameters = null)
    {
        // this method is now redundant
        // currencies are now fetched before markets
        parameters ??= new Dictionary<string, object>();
        IDictionary<string, object> options = this.safeDict(this.options, "fetchMarkets", new Dictionary<string, object>() {});
        Int64? timestamp = this.safeInteger(options, "timestamp");
        Int64? expires = this.safeInteger(options, "expires", 1000);
        Int64 now = this.milliseconds();
