    /**
     * @method
     * @name bitstamp#fetchWithdrawals
     * @description fetch all withdrawals made from an account
     * @see https://www.bitstamp.net/api/#tag/Withdrawals/operation/GetWithdrawalRequests
     * @param {string} code unified currency code
     * @param {int} [since] the earliest time in ms to fetch withdrawals for
     * @param {int} [limit] the maximum number of withdrawals structures to retrieve
     * @param {object} [params] extra parameters specific to the exchange API endpoint
     * @returns {object[]} a list of [transaction structures]{@link https://docs.ccxt.com/?id=transaction-structure}
     */
    public async override Task<List<ccxt.Transaction>> FetchWithdrawals(string code = null, Int64? since = null, Int64? limit = null, object parameters = null)
    {
        parameters ??= new Dictionary<string, object>();
        if ((this.markets == null))
        {
            await this.loadMarkets();
        }
        Dictionary<string, object> request = new Dictionary<string, object>() {};
        if ((since != null))
        {
            request["timedelta"] = (this.milliseconds() - since);
        } else
        {
            request["timedelta"] = 50000000; // use max bitstamp approved value
        }
        List<object> response = await this.privatePostWithdrawalRequests(this.extend(request, parameters));
        //
        //     [
        //         {
        //             "status": 2,
        //             "datetime": "2018-10-17 10:58:13",
